"""Apply the October 15–16 calendar and replacement SWISH artwork once."""
from pathlib import Path
import base64,json,re
IMAGES = {'assets/era-covers/swish.webp': '', 'assets/calendar/nah-nah-nah.webp': '', 'assets/calendar/venice-wedding.webp': '', 'assets/calendar/chocolate-750.webp': '', 'assets/calendar/uganda-boots.webp': '', 'assets/calendar/take-one-for-the-team.webp': '', 'assets/calendar/ys-italy.webp': ''}
EVENTS = [{'month': 10, 'day': 15, 'title': '"Heartless" Released Ahead Of 808’s And Heartbreak', 'releaseYear': 2008, 'cover': 'covers/808s.jpg', 'event': True}, {'month': 10, 'day': 15, 'title': 'The Yeezy Boost 750 "Chocolate" Released', 'releaseYear': 2016, 'cover': 'assets/calendar/chocolate-750.webp', 'event': True}, {'month': 10, 'day': 15, 'title': '"My Choice" Leaked', 'releaseYear': 2019, 'cover': 'covers/unreleased-yandhi.jpg', 'event': True}, {'month': 10, 'day': 15, 'title': '"Last Name V4" Leaked', 'releaseYear': 2019, 'cover': 'covers/unreleased-yandhi.jpg', 'event': True}, {'month': 10, 'day': 15, 'title': '"Take One For The Team" Released For GOOD Fridays', 'releaseYear': 2010, 'cover': 'assets/calendar/take-one-for-the-team.webp', 'event': True}, {'month': 10, 'day': 15, 'title': 'Ye Gifts President Of Uganda Yeezy Boots', 'releaseYear': 2018, 'cover': 'assets/calendar/uganda-boots.webp', 'event': True}, {'month': 10, 'day': 15, 'title': 'Billboard Reports Ye And Ty To Perform ¥$ In Italy (Cancelled)', 'releaseYear': 2023, 'cover': 'assets/calendar/ys-italy.webp', 'event': True}, {'month': 10, 'day': 16, 'title': '"LET GO V16" Leaked', 'releaseYear': 2024, 'cover': 'covers/vultures-2.jpg', 'event': True}, {'month': 10, 'day': 16, 'title': '"Nah Nah Nah" Released', 'releaseYear': 2020, 'cover': 'assets/calendar/nah-nah-nah.webp', 'event': True}, {'month': 10, 'day': 16, 'title': '"Rich Nigga Drunk V9" Leaked', 'releaseYear': 2018, 'cover': 'assets/era-covers/swish.webp?v=oct16', 'event': True}, {'month': 10, 'day': 16, 'title': 'Ye Performs At A Wedding In Venice', 'releaseYear': 2021, 'cover': 'assets/calendar/venice-wedding.webp', 'event': True}]
for name,encoded in IMAGES.items():
 path=Path(name);path.parent.mkdir(parents=True,exist_ok=True);path.write_bytes(base64.b64decode(encoded))
p=Path('index.html');text=p.read_text()
marker='const CALENDAR_ANNUAL_EVENTS='
match=re.search(r'const\s+CALENDAR_ANNUAL_EVENTS\s*=\s*\[',text)
assert match, 'Annual calendar array missing'
missing=[e for e in EVENTS if json.dumps(e['title'],ensure_ascii=False) not in text and json.dumps(e['title']) not in text]
text=text[:match.end()]+''.join('\n'+json.dumps(e,ensure_ascii=False)+',' for e in missing)+text[match.end():]
p.write_text(text)
p=Path('data/hosted-audio.json');data=json.loads(p.read_text());count=0
for record in data['files'].values():
 if str(record.get('era','')).strip().upper()=='SWISH':
  record['cover']='assets/era-covers/swish.webp?v=oct16';count+=1
assert count==29, f'Unexpected SWISH entry count: {count}'
p.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
print(f'Added {len(missing)} calendar events; updated {count} SWISH players')
